from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Disp_all(EmssimCommand):
    def __init__(self, method="disp_all", timeout=60, rpc_connection_name='localRPC'):
        super(Disp_all, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Disp_all, self).on_new_data(**data)
        if 'msg' in data:
            if 'attributes' not in self._ret.keys():
                self._ret['attributes'] = {}
            if data['msg'] == "Completed DISP with get attributes" or data['msg'] == "Completed DISP without attributes":
                # There should be only 1 key (object_name) in data['attributes'] per json_rpc message
                for object_name, object_dict in data['attributes'].items():
                    object_name = object_name.upper()
                    self._ret['attributes'][object_name] = {}
                    for attribute_name, attribute_value in object_dict.items():
                        if isinstance(attribute_value, list):
                            for index, row in enumerate(attribute_value):
                                if isinstance(row, dict):
                                    for field, field_value in row.items():
                                        attr_full_name = "%s.%s[%s]" % (attribute_name, field, index)
                                        self._ret['attributes'][object_name][attr_full_name.lower()] = field_value
                                else:
                                    attr_name = "%s[%s]" % (attribute_name, index)
                                    self._ret['attributes'][object_name][attr_name.lower()] = row
                        else:
                            self._ret['attributes'][object_name][attribute_name.lower()] = attribute_value
                self._change_all_booleans_and_nones(self._ret['attributes'])

            if data['msg'] == "warning occured" and "Unrecognized object:" in data['warning']:
                object_name = data['warning'].replace("Unrecognized object:", "").strip().upper()
                self._ret['attributes'][object_name] = None
        elif 'status' in data:
            self._ret['status'] = data['status']

    def _change_all_booleans_and_nones(self, dicct):
        for key, value in dicct.items():
            if isinstance(value, dict):
                self._change_all_booleans_and_nones(value)
            else:
                if value in ['false', 'False']:
                    dicct[key] = False
                elif value in ['true', 'True']:
                    dicct[key] = True
                elif value in ['none', 'None']:
                    dicct[key] = None
